//! The tronzero Tron agent (an AlphaZero-style network with PUCT search) as a
//! WebAssembly module for the blog's arcade.
//!
//! `upstream/` holds the engine from nathanWolo/tron-codingame, generated by
//! `derive.py` (see its header comments); `api.rs` sets up a game and exports
//! the functions the page calls, mirroring the masthead engine's API. The
//! folder name starts with an underscore so that Jekyll leaves it out of the site.
//!
//! The modules sit at the crate root, under the names the upstream code uses
//! for itself (`crate::board`, `crate::net`, ...).

#[allow(dead_code)]
#[path = "upstream/board.rs"]
pub mod board;
#[allow(dead_code)]
#[path = "upstream/mcts.rs"]
pub mod mcts;
#[allow(dead_code)]
#[path = "upstream/net.rs"]
pub mod net;
#[allow(dead_code)]
#[path = "upstream/play.rs"]
pub mod play;

pub mod api;

/// The weights, packed by upstream's `tools/make_paste.py`.
pub const NET_PACKED: &str = include_str!("../net_packed.txt");

/// Search settings, upstream's `C_PUCT` and `FPU_REDUCTION` (main.rs).
pub const C_PUCT: f32 = 0.6;
pub const FPU_REDUCTION: f32 = 0.2;
